"""SQLite storage for the generated task manager."""

from __future__ import annotations

import sqlite3
from pathlib import Path

DATABASE_PATH = Path(__file__).with_name('tasks.db')


def connect() -> sqlite3.Connection:
    return sqlite3.connect(DATABASE_PATH)


def initialize() -> None:
    with connect() as connection:
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                completed INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
            """
        )


def add_task(title: str) -> int:
    with connect() as connection:
        cursor = connection.execute("INSERT INTO tasks (title) VALUES (?)", (title,))
        return int(cursor.lastrowid)


def list_tasks() -> list[tuple[int, str, int]]:
    with connect() as connection:
        return connection.execute("SELECT id, title, completed FROM tasks ORDER BY id").fetchall()


def complete_task(task_id: int) -> bool:
    with connect() as connection:
        cursor = connection.execute("UPDATE tasks SET completed = 1 WHERE id = ?", (task_id,))
        return cursor.rowcount == 1
